import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Installer Kodus","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installer.md","filePath":"guide/installer.md"}'),r={name:"guide/installer.md"};function i(n,e,l,u,d,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="installer-kodus" tabindex="-1">Installer Kodus <a class="header-anchor" href="#installer-kodus" aria-label="Permalink to &quot;Installer Kodus&quot;">​</a></h1><p>Les fichiers d&#39;installation sont disponibles sur la <a href="https://github.com/Dusko01/kodus-releases/releases/latest" target="_blank" rel="noreferrer">page des versions</a>, dans la section <strong>Assets</strong>.</p><table tabindex="0"><thead><tr><th>Fichier</th><th>Usage</th></tr></thead><tbody><tr><td><code>Kodus-Setup-….exe</code></td><td>Windows, recommandé (mises à jour automatiques)</td></tr><tr><td><code>Kodus-…-portable.zip</code></td><td>Windows, si l&#39;installeur est bloqué</td></tr><tr><td><code>Kodus-…-mac-arm64.dmg</code></td><td>Mac équipé d&#39;une puce Apple (M1, M2, M3…)</td></tr><tr><td><code>Kodus-…-mac-x64.dmg</code></td><td>Mac équipé d&#39;un processeur Intel</td></tr></tbody></table><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>Téléchargez <code>Kodus-Setup-….exe</code>, puis lancez-le.</li><li>Windows affiche l&#39;écran « Windows a protégé votre ordinateur ». Ce message apparaît parce que Kodus n&#39;est pas signé numériquement, et non parce qu&#39;il est dangereux. Cliquez sur <strong>Informations complémentaires</strong>, puis sur <strong>Exécuter quand même</strong>.</li><li>Suivez les étapes de l&#39;installation. Kodus se mettra ensuite à jour automatiquement.</li></ol><h2 id="si-windows-bloque-l-installation-sans-proposer-«-executer-quand-meme-»" tabindex="-1">Si Windows bloque l&#39;installation sans proposer « Exécuter quand même » <a class="header-anchor" href="#si-windows-bloque-l-installation-sans-proposer-«-executer-quand-meme-»" aria-label="Permalink to &quot;Si Windows bloque l&#39;installation sans proposer « Exécuter quand même »&quot;">​</a></h2><p>Ce blocage provient du Contrôle intelligent des applications de Windows 11. Deux solutions sont possibles.</p><h3 id="a-utiliser-la-version-portable-sans-mises-a-jour-automatiques" tabindex="-1">A) Utiliser la version portable (sans mises à jour automatiques) <a class="header-anchor" href="#a-utiliser-la-version-portable-sans-mises-a-jour-automatiques" aria-label="Permalink to &quot;A) Utiliser la version portable (sans mises à jour automatiques)&quot;">​</a></h3><ol><li>Téléchargez <code>Kodus-…-portable.zip</code>.</li><li>Faites un clic droit sur le fichier → <strong>Extraire tout</strong>, puis placez le dossier obtenu à l&#39;emplacement de votre choix (évitez le dossier Téléchargements, pour ne pas le supprimer par erreur).</li><li>Lancez <code>Kodus.exe</code> depuis ce dossier. Pour créer un raccourci : clic droit → <strong>Afficher d&#39;autres options</strong> → <strong>Envoyer vers</strong> → <strong>Bureau (créer un raccourci)</strong>.</li></ol><h3 id="b-desactiver-temporairement-la-protection-operation-unique" tabindex="-1">B) Désactiver temporairement la protection (opération unique) <a class="header-anchor" href="#b-desactiver-temporairement-la-protection-operation-unique" aria-label="Permalink to &quot;B) Désactiver temporairement la protection (opération unique)&quot;">​</a></h3><ol><li>Ouvrez les <strong>Paramètres</strong> de Windows (touches Windows + I) → <strong>Confidentialité et sécurité</strong> → <strong>Sécurité Windows</strong>.</li><li>Cliquez sur <strong>Ouvrir Sécurité Windows</strong>.</li><li>Accédez à <strong>Contrôle des applications et du navigateur</strong> → <strong>Paramètres du contrôle intelligent des applications</strong>.</li><li>Sélectionnez <strong>Désactivé</strong>.</li><li>Double-cliquez sur <code>Kodus-Setup-….exe</code> pour lancer l&#39;installeur.</li><li>Sur l&#39;écran « Windows a protégé votre ordinateur », cliquez sur <strong>Informations complémentaires</strong>, puis sur <strong>Exécuter quand même</strong>, et suivez l&#39;installation.</li><li>Une fois Kodus installé, revenez au même emplacement et <strong>réactivez</strong> la protection.</li></ol><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Configuration requise : macOS 13 (Ventura) ou version ultérieure</p><p>Cela correspond approximativement aux Mac commercialisés à partir de 2017. Pour connaître votre version : menu Pomme → <strong>À propos de ce Mac</strong>.</p></div><ol><li>Menu Pomme → <strong>À propos de ce Mac</strong> : si la mention « Puce Apple M… » apparaît, téléchargez <code>Kodus-…-mac-arm64.dmg</code> ; sinon, <code>Kodus-…-mac-x64.dmg</code>.</li><li>Ouvrez le fichier <code>.dmg</code> et faites glisser Kodus dans le dossier <strong>Applications</strong>.</li><li>Au premier lancement, macOS refuse d&#39;ouvrir l&#39;application. Cliquez sur <strong>OK</strong>, puis ouvrez <strong>Réglages Système</strong> → <strong>Confidentialité et sécurité</strong> et cliquez, en bas de la page, sur <strong>Ouvrir quand même</strong>. Cette opération n&#39;est à faire qu&#39;une fois.</li><li>Si macOS indique que Kodus est « endommagé » (ce qui n&#39;est pas le cas), ouvrez l&#39;application <strong>Terminal</strong>, collez la commande suivante, puis appuyez sur Entrée :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Kodus.app</span></span></code></pre></div><p>Étape suivante : <a href="./premier-lancement">Premier lancement</a>.</p>',16)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
